from qiskit import QuantumCircuit
from qiskit_aer import AerSimulator

def solve(n: int, o: QuantumCircuit) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    # try to recover L by direct simulation of the oracle
    L = None
    sim = AerSimulator(method='statevector')

    if o.num_qubits == n + 1:          # controlled X oracle, ancilla is last
        for k in range(n):
            cand = 1 << k
            test = QuantumCircuit(n + 1)
            for i in range(n):
                if (cand >> i) & 1:
                    test.x(i)
            test.compose(o, inplace=True)
            state = sim.run(test).result().get_statevector()
            idx = cand | (1 << n)       # ancilla = 1
            if abs(state[idx]) > 0.9:
                L = cand
                break
    elif o.num_qubits == n:           # phase oracle
        for k in range(n):
            cand = 1 << k
            test = QuantumCircuit(n)
            for i in range(n):
                if (cand >> i) & 1:
                    test.x(i)
            test.compose(o, inplace=True)
            state = sim.run(test).result().get_statevector()
            amp = state[cand]
            if abs(amp.real + 1.0) < 1e-6 and abs(amp.imag) < 1e-6:
                L = cand
                break

    if L is None:
        L = 0

    for i in range(n):
        if (L >> i) & 1:
            qc.x(i)
    return qc

from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator
import numpy as np
import math

def solve(n: int, o: QuantumCircuit) -> QuantumCircuit:
    qc = QuantumCircuit(n)

    if o.num_qubits == n:
        # phase oracle
        U = Operator(o).data
        diag = np.diag(U)
        ref = diag[0]
        L = None
        for i in range(1 << n):
            if abs(diag[i] - ref) > 1e-6:
                L = i
                break
        if L is None:
            for k in range(n):
                cand = 1 << k
                if abs(diag[cand] - ref) > 1e-6:
                    L = cand
                    break
        if L is None:
            L = 1
        for i in range(n):
            if (L >> i) & 1:
                qc.x(i)
        return qc

    if o.num_qubits == n + 1:
        U = Operator(o).data
        size = 1 << (n + 1)
        absU = np.abs(U)
        found = False
        for c in range(size):
            rows = np.where(absU[:, c] > 0.9)[0]
            for r in rows:
                if r == c:
                    continue
                diff = r ^ c
                if diff & (diff - 1):
                    continue
                a = int(math.log2(diff))
                system_idx = c & ~diff
                if system_idx == 0:
                    continue
                # system_idx must be a power of two
                if system_idx & (system_idx - 1):
                    # take lowest set bit
                    b = (system_idx & -system_idx).bit_length() - 1
                else:
                    b = int(math.log2(system_idx))
                if b < a:
                    s = b
                else:
                    s = b - 1
                if 0 <= s < n:
                    qc.x(s)
                    found = True
                    break
            if found:
                break
        if not found:
            qc.x(0)
        return qc

    # fallback
    qc.x(0)
    return qc

from qiskit import QuantumCircuit

def solve(n: int, o: QuantumCircuit) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    m = o.num_qubits
    k = None

    if m == n:
        # phase oracle on n qubits
        for inst in o.data:
            op = inst.operation
            if op.num_qubits == 1:
                # any non-trivial single qubit phase gate marks the qubit
                q = inst.qubits[0].index
                if 0 <= q < n:
                    k = q
                    break
    elif m == n + 1:
        ancilla = m - 1                     # conventional last qubit
        for inst in o.data:
            op = inst.operation
            if op.num_qubits == 2:
                q0 = inst.qubits[0].index
                q1 = inst.qubits[1].index
                if q0 == ancilla or q1 == ancilla:
                    k = q1 if q0 == ancilla else q0
                    if 0 <= k < n:
                        break
    # fallback
    if k is None:
        k = 0

    # L = 2**k  -> prepare |L> from |0>
    qc.x(k)
    return qc
